"""Create a separately frozen research release and lock retrospective protocol before scoring."""
from pathlib import Path
import json,hashlib,joblib,datetime
root=Path(__file__).resolve().parents[2];sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest();candidate=root/'models/raw-v2.2-candidate';release=root/'models/raw-v2.2'
def main():
 if (root/'config/v22-evaluation-lock.json').exists():raise ValueError('Evaluation already locked; do not overwrite')
 release.mkdir(exist_ok=True);b=joblib.load(candidate/'lunge-detector.joblib');b.update(release_version='2.2.0',release_status='frozen-retrospective-research-release',scientific_status='retrospective development evaluation; no independent generalization or accuracy improvement established');joblib.dump(b,release/'lunge-detector.joblib',compress=3)
 c={'release_version':'2.2.0','mode':'raw-video-only','threshold':b['threshold'],'event_rules':b['event_rules'],'source_feature_names':b['source_feature_names'],'feature_engineering_version':0,'model_sha256':sha(release/'lunge-detector.joblib'),'adapter_sha256':sha(root.parent/'raw-video-integration/day5/adapter.py'),'scientific_status':b['scientific_status'],'candidate_source_sha256':sha(candidate/'lunge-detector.joblib'),'training_recordings':['movie1','movie2','movie3','movie4'],'selection_recordings':['movie5'],'identity_policy':'native source identities; no unsupported reference-assisted correction integrated'}
 (release/'configuration.json').write_text(json.dumps(c,indent=2)+'\n');(release/'freeze-manifest.json').write_text(json.dumps({'files':{n:sha(release/n) for n in ['configuration.json','lunge-detector.joblib']}},indent=2)+'\n')
 protocol={'locked_utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'fallback':'retrospective; supplied known collection has movies1–10 only, all previously consumed','recordings':{f'movie{i}':('training-resubstitution' if i<=4 else 'retrospective-development-selection') for i in range(1,6)},'independent_recordings':[],'previously_consumed_movies_excluded':[6,7,8,9,10],'model_files':{str(p):sha(p) for p in [release/'lunge-detector.joblib',release/'configuration.json',candidate/'lunge-detector.joblib',root.parent/'flyaggression-v2.1/models/raw-v2.1/lunge-detector.joblib']},'threshold':.15,'event_rules':{'median_window':3,'max_gap_frames':1,'min_event_frames':3},'event_iou':.3,'coverage':'identical Version2.1 eligible frames and whole-bout event censoring; no exclusions relaxed','features':b['source_feature_names'],'tuning_allowed':False,'inference_annotations':'labels/reference tracks used only after inference for retrospective metrics','diameter_status':'nominal16mm, not individually measured','fresh_functional_demo':'full movie1; not independent accuracy; no annotations during inference'}
